-- =============================================================================
-- 034 : RCP BDPM condensé → matrice_medicaments (Cardio DEUST 2A)
-- Généré par sql/ops/cardio_rcp_matrice_gen.mjs — NE PAS éditer à la main.
-- Matrice / référentiel uniquement ; publications DEUST = source cours (035).
-- EI : fréquents ou rares graves. Idempotent (jp_fill sans doublon).
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.jp_ent(p_table text, p_valeur text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_id uuid; v_norm text := jeupharma.normaliser_valeur(p_valeur);
BEGIN
  EXECUTE format('SELECT id FROM jeupharma.%I WHERE valeur_norm = $1 AND actif LIMIT 1', p_table) INTO v_id USING v_norm;
  IF v_id IS NULL THEN
    EXECUTE format('INSERT INTO jeupharma.%I (valeur, valeur_norm) VALUES ($1, $2) RETURNING id', p_table) INTO v_id USING p_valeur, v_norm;
  END IF;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_fill(p_matrice uuid, p_champ text, p_vals text[])
RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_tbl text; v_jt text; v_fk text; v_id uuid; i int;
BEGIN
  SELECT t.ent, t.jt, t.fk INTO v_tbl, v_jt, v_fk FROM (VALUES
    ('secteurs','secteurs_therapeutiques','matrice_secteurs_therapeutiques','secteur_therapeutique_id'),
    ('ct','classes_therapeutiques','matrice_classes_therapeutiques','classe_therapeutique_id'),
    ('cp','classes_pharmacologiques','matrice_classes_pharmacologiques','classe_pharmacologique_id'),
    ('ind','indications','matrice_indications','indication_id'),
    ('ci','contre_indications','matrice_contre_indications','contre_indication_id'),
    ('ei','effets_indesirables','matrice_effets_indesirables','effet_indesirable_id'),
    ('pre','precautions_emploi','matrice_precautions_emploi','precaution_emploi_id'),
    ('inter','interactions','matrice_interactions','interaction_id'),
    ('surv','surveillances','matrice_surveillances','surveillance_id'),
    ('noms','noms_commerciaux','matrice_noms_commerciaux','nom_commercial_id')
  ) AS t(champ, ent, jt, fk) WHERE t.champ = p_champ;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'champ inconnu %', p_champ; END IF;
  IF p_vals IS NULL THEN RETURN; END IF;
  FOR i IN 1 .. coalesce(array_length(p_vals, 1), 0) LOOP
    v_id := pg_temp.jp_ent(v_tbl, p_vals[i]);
    EXECUTE format(
      'INSERT INTO jeupharma.%I (matrice_id, %I, ordre) SELECT $1, $2, $3 WHERE NOT EXISTS (SELECT 1 FROM jeupharma.%I WHERE matrice_id = $1 AND %I = $2)',
      v_jt, v_fk, v_jt, v_fk) USING p_matrice, v_id, i - 1;
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_matrice_by_norm(p_norm text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_m uuid;
BEGIN
  SELECT m.id INTO v_m FROM jeupharma.matrice_medicaments m
  JOIN jeupharma.dcis d ON d.id = m.dci_id
  WHERE d.valeur_norm = jeupharma.normaliser_valeur(p_norm) AND m.statut = 'publie' LIMIT 1;
  IF v_m IS NULL THEN RAISE EXCEPTION 'fiche publie introuvable norm=%', p_norm; END IF;
  RETURN v_m;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_detail_set(p_matrice uuid, p_valeur text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  UPDATE jeupharma.matrice_medicaments
  SET detail_pharmacologie_id = pg_temp.jp_ent('details_pharmacologie', p_valeur), updated_at = now()
  WHERE id = p_matrice;
END $$;

DO $mig$
DECLARE
  m uuid;
BEGIN

-- DCI ignorées (pas de CIS sûr) : acide folinique (no_safe_candidate); epoetine alfa (empty_rcp); epoetine beta (empty_rcp); darbepoetine alfa (empty_rcp); rivaroxaban (empty_rcp); apixaban (empty_rcp); idarucizumab (empty_rcp); desirudine (no_search_hit); lepirudine (no_search_hit); tenecteplase (empty_rcp); reteplase (no_search_hit); streptokinase (no_search_hit); urokinase (no_safe_candidate); alginate de calcium (no_search_hit); isosorbide dinitrate (no_safe_candidate); ivabradine (empty_rcp); dapagliflozine (empty_rcp); ginkgo biloba (empty_rcp); ruscoside (no_search_hit); propranolol (empty_rcp); timolol (no_safe_candidate); triamterene (no_safe_candidate); eprosartan (no_search_hit)
  -- sels ferreux (CIS 61879666, allowlist)
  m := pg_temp.jp_matrice_by_norm('sels ferreux');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : PREPARATIONS ANTIANEMIQUES – PREPARATIONS A BASE DE FER - Code ATC : B03AA07.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement préventif de la carence martiale de la femme enceinte, lorsqu’un apport alimentaire suffisant en fer ne peut être assuré.', 'TARDYFERON 50 mg est uniquement indiqué chez les femmes enceintes.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Surcharge martiale en particulier anémie normo ou hypersidérémique telle que thalassémie, anémie réfractaire, anémie par insuffisance médullaire.', 'Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['L’hyposidérémie associée aux syndromes inflammatoires n’est pas sensible au traitement martial.', 'Le traitement martial doit, dans la mesure du possible, être associé au traitement de la cause.', 'Les patients âgés et les patients ayant des difficultés à avaler ne doivent être traités avec des comprimés de sulfate de fer qu''après une évaluation minutieuse du risque d''inhalation du patient.', 'Des formulations alternatives doivent être envisagées.', 'Les patients doivent consulter un médecin en cas de suspicion d''inhalation (voir rubrique 4.8).', 'Cette pigmentation peut gêner une chirurgie gastro-intestinale et doit donc être prise en compte, en particulier lors de la chirurgie programmée.', 'Il est donc souhaitable de prévenir le chirurgien de la supplémentation en fer en cours, compte tenu de ce risque (voir rubrique 4.8).', 'En raison du risque d’ulcérations buccales et d’altération de la couleur dentaire, les comprimés ne doivent pas être sucés, mâchés ou gardés dans la bouche, mais avalés entiers avec de l’eau.', 'Ce médicament contient moins de 1 mmol de sodium (23 mg) par comprimé c’est-à-dire qu’il est essentiellement sans sodium.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées', '+ Fer (sels de) (voie injectable)', 'Lipothymie, voire choc attribué à la libération rapide du fer de sa forme complexe et à la saturation de la sidérophiline.', 'Associations à prendre en compte', '+ Acide acétohydroxamique', 'Diminution de l’absorption digestive de ces deux médicaments par chélation du fer.', 'Associations faisant l''objet de précautions d’emploi', '+ Bictégravir', 'Diminution de près des deux tiers de l’absorption du bictégravir en cas d’ingestion simultanée ou à jeun.', 'Prendre le bictégravir au moins 2 heures avant les sels de fer, ou en même temps qu’un repas.', '+ Bisphophonates', 'Diminution de l''absorption digestive des bisphosphonates.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables sont répertoriés selon la classification de systèmes d’organes MedDRA et énumérés ci-dessous comme : très fréquent (≥ 1/10), fréquent (≥1/100,', 'Fréquent', '(≥ 1/100', 'Peu fréquent', 'Fréquent indéterminée']);

  -- acide ascorbique (CIS 69435752, scored)
  m := pg_temp.jp_matrice_by_norm('acide ascorbique');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ACIDE ASCORBIQUE (VIT C), NON ASSOCIEE (A: Voies digestives et métabolisme), code ATC : A11GA01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement d''appoint de l''asthénie fonctionnelle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1', 'En raison de la présence d''aspartam, ce médicament est contre-indiqué en cas de phénylcétonurie', 'Néphrolithiase ou antécédents de néphrolithiase, notamment lithiase rénale oxalo-calcique', 'Hyperoxalurie', 'Insuffisance rénale sévère (clairance de la créatinine', 'Enfants et adolescents de moins de 15 ans.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Ce médicament contient du saccharose (1070 mg par comprimé).', 'Son utilisation est déconseillée chez les patients présentant une intolérance au fructose, un syndrome de malabsorption du glucose et du galactose ou un déficit en sucrase/isomaltase.', 'Ce médicament contient du sodium.', 'Ce médicament contient 0,257 g de sodium par comprimé, ce qui équivaut à 12,85 % de l’apport alimentaire quotidien maximal recommandé par l’OMS de 2 g de sodium par adulte.', 'A prendre en compte chez les patients suivant un régime hyposodé strict.', 'En cas de persistance des troubles au-delà de 1 mois de traitement ou d''aggravation des troubles, une recherche étiologique doit être effectuée et la conduite à tenir réévaluée.', 'En raison d''un effet légèrement stimulant, il est souhaitable de ne pas prendre la vitamine C en fin de journée.', 'Prendre en compte les apports en vitamine C issus d’autres sources, comme les médicaments, les aliments enrichis et les compléments alimentaires (voir rubriques 4.5 et 4.9).', 'L’acide ascorbique (vitamine C) augmente l’absorption gastro-intestinale du fer.', 'En cas d’hémochromatose, l’utilisation de ce médicament doit faire l’objet de précautions strictes (voir rubrique 4.5).', 'L’acide ascorbique peut fausser les résultats de certaines analyses biologiques, notamment les tests de contrôle du glucose sanguin et urinaire (voir rubrique 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations faisant l''objet de précautions d’emploi', '+ DEFEROXAMINE', 'Augmentation du risque d’insuffisance cardiaque induite par le fer en raison d’une augmentation de la mobilisation du fer par une supplémentation supraphysiologique en vitamine C.', 'En cas d''hémochromatose, ne donner de la vitamine C qu''après avoir commencé le traitement par la déféroxamine.', 'Surveiller la fonction cardiaque en cas d''association.', 'Associations à prendre en compte', '+ CICLOSPORINE', 'Risque de diminution des concentrations en ciclosporine, notamment en cas d’association avec la vitamine E.', 'Interactions avec d’autres supplémentations en vitamines et /ou minéraux', 'Certains médicaments peuvent interagir avec certaines vitamines et/ou minéraux à des doses nettement plus élevées que celles présentes dans LAROSCORBINE 1 g, comprimé effervescent.', 'Autres formes d’interactions', 'Dans ce cas, il est préférable d’utiliser des tests adaptés ou n’impliquant pas de réactions d’oxydo-réductions ou d’arrêter la prise de vitamine C afin d’éviter des interférences.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Voir rubrique 4.9.', 'Déclaration des effets indésirables suspectés', 'La déclaration des effets indésirables suspectés après autorisation du médicament est importante.', 'Elle permet une surveillance continue du rapport bénéfice/risque du médicament.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L’acide ascorbique peut fausser les résultats de certaines analyses biologiques, notamment les tests de contrôle du glucose sanguin et urinaire (voir rubrique 4.5).']);

  -- colecalciferol (CIS 63902334, allowlist)
  m := pg_temp.jp_matrice_by_norm('colecalciferol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : VITAMINE D ET ANALOGUES, code ATC : A11CC05 (A: Appareil digestif et métabolisme)');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement et/ou prophylaxie de la carence en vitamine D.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'Hypercalcémie, hypercalciurie, lithiase calcique,', 'Hypervitaminose D,', 'Néphrocalcinose,', 'Pathologie et/ou conditions entraînant une hypercalcémie et/ou une hypercalciurie.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Surveillance', 'Sarcoïdose', 'Chez ces patients, il convient de surveiller étroitement la calcémie et la calciurie.', 'Insuffisance rénale', 'Ce médicament doit être utilisé avec prudence chez les patients présentant une insuffisance rénale et l''effet sur les taux de calcium et de phosphate doit être surveillé.', 'Le risque de calcification des tissus mous doit être pris en compte.', 'Patients sous digoxine', 'L’effet de la vitamine D sur la calcémie devra inciter à une surveillance accrue des patients sous digoxine vis-à-vis du risque d''arythmies cardiaques.', 'Patients sous diurétiques thiazidiques', 'Il existe un risque accru d''hypercalcémie lors de l''utilisation concomitante de diurétiques thiazidiques car ils réduisent l''excrétion urinaire du calcium.', 'Toxicité de la vitamine D en situation d’hypervitaminose D']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Précaution d’emploi', '+ ANTICONVULSIVANTS INDUCTEURS ENZYMATIQUES (carbamazépine, fosphénytoïne, phénobarbital, phénytoïne, primidone ou barbituriques)', 'Diminution des concentrations de vitamine D plus marquée qu’en l’absence d''inducteur enzymatique.', 'Dosage des concentrations de vitamine D et supplémentation si nécessaire.', '+ GLUCOCORTICOÏDES', 'Les glucocorticoïdes réduisent l''effet de la vitamine D en raison d''un métabolisme accru.', 'Dosage des concentrations de vitamine D et supplémentation vitaminocalcique si nécessaire.', '+ RESINES CHELATRICES', 'La prise de résine chélatrice peut diminuer l’absorption intestinale et, potentiellement, l’efficacité d’autres médicaments pris simultanément.', 'D’une façon générale, la prise de la résine doit se faire à distance de celle des autres médicaments, en respectant un intervalle de plus de 2 heures, si possible.', '+ RIFAMPICINE', 'Diminution des concentrations plasmatiques de vitamine D plus marquée qu’en l’absence de traitement par la rifampicine.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Au sein de chaque système classe-organe, les événements indésirables sont présentés par ordre décroissant de fréquence selon la convention suivante : très fréquent (≥1/10), fréquent (>1/100, 1/1 000, ']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Surveillance', 'Chez ces patients, il convient de surveiller étroitement la calcémie et la calciurie.', 'Ce médicament doit être utilisé avec prudence chez les patients présentant une insuffisance rénale et l''effet sur les taux de calcium et de phosphate doit être surveillé.', 'L’effet de la vitamine D sur la calcémie devra inciter à une surveillance accrue des patients sous digoxine vis-à-vis du risque d''arythmies cardiaques.']);

  -- cyanocobalamine (CIS 61247741, allowlist)
  m := pg_temp.jp_matrice_by_norm('cyanocobalamine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ANTIANEMIQUE - VITAMINE B12, code ATC : B03BA01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Anémie par carence d''apport alimentaire en vitamine B12 chez les végétaliens stricts depuis plus de 4 ans.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Enfants de moins de 6 ans, en raison de la forme pharmaceutique.', 'Antécédents d''allergie aux cobalamines (vitamine B12 et substances apparentées).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Ce médicament contient du glucose.', 'Les patients présentant un syndrome de malabsorption du glucose et du galactose (maladie héréditaire rare) ne doivent pas prendre ce médicament.', 'Ce médicament contient du lactose.', 'Les patients présentant une intolérance au galactose, un déficit total en lactase ou un syndrome de malabsorption du glucose et du galactose (maladies héréditaires rares) ne doivent pas prendre ce médicament.', 'Ce médicament contient du saccharose.', 'Les patients présentant une intolérance au fructose, un syndrome de malabsorption du glucose et du galactose ou un déficit en sucrase/isomaltase (maladies héréditaires rares) ne doivent pas prendre ce médicament.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations à prendre en compte', '+ Anti-sécrétoires antihistaminiques H2', 'Risque de carence en cyanocobalamine après traitement prolongé (quelques années), la réduction de l''acidité gastrique par ces médicaments pouvant diminuer l''absorption digestive de la vitamine B12.', '+ Anti-sécrétoires inhibiteurs de la pompe à protons']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquent (≥ 1/100, Tableau des effets indésirables :', 'Réactions d’hypersensibilité comprenant prurit, urticaire, eczéma, érythème, œdème, pouvant être sévères, donnant lieu à un œdème généralisé, un angioedème, voire un choc anaphylactique']);

