  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Patients atteints d’un cancer folate-dépendant.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Avant un traitement par FERTIFOL, il convient d’évaluer attentivement les conditions cliniques suivantes, pouvant nécessiter des doses plus élevées d’acide folique :', 'patiente ayant déjà donné naissance à un enfant (ou avorté d’un fœtus) présentant une anomalie de fermeture du tube neural ;', 'patiente sous traitement antiépileptique : carbamazépine ou acide valproïque ;', 'antécédents familiaux d’anomalie de fermeture du tube neural ;', 'patiente traitée par des antagonistes de l’acide folique (méthotrexate, sulphasalazine) (voir rubrique 4.5),', 'patientes présentant une anémie mégaloblastique liée à un apport insuffisant en acide folique.', 'Ceci peut conduire à des atteintes majeures du système nerveux avant qu’un diagnostic correct soit établi.', 'Chez les femmes traitées par des antagonistes de l’acide folique, il convient d’administrer de l’acide folinique plutôt que des doses plus élevées d’acide folique.', 'L’administration concomitante de FERTIFOL et de phénobarbital, phénytoïne ou primidone n’est pas recommandée (voir rubrique 4.5).', 'Ce médicament contient du lactose.', 'Les patients présentant une intolérance au galactose, un déficit total en lactase ou un syndrome de malabsorption du glucose et du galactose (maladies héréditaires rares) ne doivent pas prendre ce médicament.', 'Ce médicament contient moins de 1 mmol (23 mg) de sodium par comprimé, c’est-à-dire qu’il est essentiellement « sans sodium ».']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['FERTIFOL peut réduire les concentrations plasmatiques de phénobarbital, de phénytoïne et de primidone en augmentant leur métabolisme.', 'Par conséquent, l’administration concomitante de FERTIFOL et de phénobarbital, de phénytoïne ou de primidone n’est pas recommandée (voir rubrique 4.4).', 'Si nécessaire, un dosage précis des concentrations plasmatiques de ces antiépileptiques devra être fait.', 'Le méthotrexate ou la sulphasalazine peuvent diminuer l’effet de l’acide folique du fait de leur propriété antagoniste.', 'L’administration simultanée de chloramphénicol et d’acide folique peut fausser la réponse hématopoïétique à l’acide folique, par antagonisme.']);
