  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Risque hémorragique', 'Au cours du traitement, un saignement peut se produire à n’importe quel endroit.', 'Une chute inexpliquée du taux d’hémoglobine et/ou de l’hématocrite ou une baisse de la pression artérielle doivent faire rechercher une source de saignement.', 'L’efficacité et la sécurité de l’idarucizumab n’ont pas été établies chez les patients pédiatriques.', 'L’hémodialyse permet d’éliminer le dabigatran.', 'Dans des études cliniques, le dabigatran étexilate a été associé à des taux plus élevés de saignement gastro-intestinal (GI) majeur.', 'Un risque accru a été observé chez les personnes âgées (≥ 75 ans) pour la posologie de 150 mg deux fois par jour.', 'Facteurs de risque', 'Le tableau 5 récapitule les facteurs pouvant majorer le risque hémorragique.', 'Tableau 5 : Facteurs pouvant majorer le risque hémorragique', 'Facteur de risque', 'Facteurs pharmacodynamiques et pharmacocinétiques']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Interactions avec des transporteurs', 'Le dabigatran étexilate est un substrat du transporteur d’efflux P-gp.', 'L’administration concomitante d’un inhibiteur de la P-gp (voir tableau 9) devrait augmenter les concentrations plasmatiques de dabigatran.', 'Des diminutions de la posologie peuvent être nécessaires en cas d’association avec certains inhibiteurs de la P-gp (voir rubriques 4.2, 4.3, 4.4 et 5.1).', 'Tableau 9 : Interactions avec des transporteurs', 'Inhibiteurs de la P-gp', 'Utilisation concomitante contre-indiquée (voir rubrique 4.3)', 'Kétoconazole', 'Dronédarone', 'Itraconazole, ciclosporine', 'Compte tenu des résultats in vitro, un effet similaire à celui obtenu avec le kétoconazole peut être attendu.', 'Glécaprévir/ pibrentasvir']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Ils sont classés par système classe organe (SOC) et fréquence selon la convention suivante : très fréquent (≥ 1/10) ; fréquent (≥ 1/100, ≥ 1/1 000, ≥ 1/10 000, Tableau 12 : Effets indésirables', 'Peu fréquent']);

  -- warfarine (CIS 64631925, scored)
