  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables sont classés par système organe et par fréquence, selon la règle suivante : très fréquent (> 10) ; fréquent (> 1/100, 1/1000 ; 1/10 000,', 'Les manifestations hémorragiques représentent la complication la plus fréquente du traitement.', 'Une hémorragie, pouvant varier d’un saignement léger à grave (y compris d’issue fatale), peut survenir au cours du traitement par COUMADINE.', 'Une hémorragie rétropéritonéale peut également se produire.', 'voies respiratoires (épistaxis, hémoptysie), y compris de rares cas d’hémorragie alvéolaire pulmonaire']);

