  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Hémorragies : Les manifestations hémorragiques représentent la complication la plus fréquente du traitement avec MINI-SINTROM.', 'Toute structure anatomique peut en être le point de départ et/ou le siège : hémorragie ou hématome intracérébral, hématome du psoas, hémorragie intra-abdominale, hémorragie intra-articulaire.', 'Il peut s’agir d’hémorragies non graves par exemple : hématome, épistaxis, gingivorragie.', 'Anémie (secondaire à une hémorragie, un saignement)', 'Fréquent :']);

