  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit pas être prescrit dans les cas suivants :', 'hypotension marquée avec état de choc.', 'association aux inhibiteurs de la phosphodiestérase de type 5 (sildénafil, tadalafil, vardénafil) (voir rubriques 4.5 et 4.4) :', 'o chez tout patient traité par la molsidomine on ne doit pas prescrire d’inhibiteurs de la phosphodiestérase de type 5 tant que le patient est sous l''action de la molsidomine.', 'o En cas de traitement par les inhibiteurs de la phosphodiestérase de type 5, la molsidomine est contre-indiquée.', 'hypersensibilité à la molsidomine ou à l’un des excipients.', 'Ce médicament est généralement déconseillé en cas d''allaitement (voir rubrique 4.6).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Association de la molsidomine aux inhibiteurs de la phosphodiestérase de type 5 (sildénafil, tadalafil, vardénafil) :', 'Excipients', 'Ce médicament contient du lactose.', 'Son utilisation est déconseillée chez les patients présentant une intolérance au galactose, un déficit en lactase de Lapp ou un syndrome de malabsorption du glucose ou du galactose (maladies héréditaires rares).', 'Précautions d''emploi', 'Une légère baisse de la pression artérielle est habituelle sous molsidomine.', 'Une posologie progressive est recommandée en cas d''insuffisance hépatocellulaire.', 'Dénuée de tout effet dépresseur myocardique, la molsidomine peut être associée aux bêta-bloquants.', 'Elle est dépourvue d''effet sur le tissu de conduction.', 'La substitution aux dérivés nitrés retard est plus logique que l''association, en raison d''une action commune sur la précharge.', 'Il n''est pas logique d''associer la molsidomine avec les dérivés nitrés d''action prolongée dans la mesure où leur mécanisme d''action est similaire.', 'Alcaloïdes de l’ergot de seigle : Une interaction pharmacodynamique (effet antagoniste), entre les donneurs de monoxyde d’azote (NO) et les alcaloïdes de l’ergot de seigle est possible.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', '+ Inhibiteurs de la phosphodiestérase de type 5 (sildénafil, tadalafil, vardénafil).', 'Risque d''hypotension importante (effet synergique) pouvant aggraver l''état d''ischémie myocardique et provoquer notamment un accident coronarien aigu.', '+ Riociguat', 'Risque d’hypotension importante (effet synergique)', 'Associations faisant l''objet de précautions d’emploi', 'En effet, les effets hypotensifs peuvent être majorés.', 'Associations à prendre en compte', '+ Dapoxétine', 'Risque de majoration des effets indésirables, notamment à type de vertiges ou de syncopes.', '+ Médicaments abaissant la pression artérielle', 'Majoration du risque d’hypotension, notamment orthostatique.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Des céphalées habituellement modérées et une légère baisse tensionnelle peuvent apparaître en début de traitement.', 'Les céphalées régressent en général spontanément en quelques jours.', 'Ces effets peuvent être majorés par la prise simultanée d''autres vasodilatateurs.', 'Une posologie progressive permet d''en réduire la fréquence.', 'Exceptionnellement, ont été signalés une hypotension orthostatique, des troubles digestifs, des vertiges ou un prurit.', 'De rares cas de thrombopénie ont été rapportés.']);

  -- nicorandil (CIS 61613167, scored)
  m := pg_temp.jp_matrice_by_norm('nicorandil');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Autres vasodilatateurs en cardiologie, Code ATC : C01DX16');
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité au nicorandil ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Choc (notamment choc cardiogénique), hypotension sévère, ou dysfonction ventriculaire gauche associée à une faible pression de remplissage ou à une décompensation cardiaque.', 'Utilisation d’inhibiteurs de la phosphodiestérase 5, car ceux-ci sont susceptibles d’entraîner une baisse importante de la pression artérielle (voir rubrique 4.5).', 'Utilisation de stimulateur(s) de la guanylate cyclase soluble (tels que le riociguat), car ceux-ci sont susceptibles d’entraîner une baisse importante de la pression artérielle (voir rubrique 4.5).', 'Hypovolémie.', 'Œdème aigu du poumon.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Ulcérations', 'Des ulcérations gastro-intestinales, de la peau et des muqueuses ont été rapportées avec le nicorandil (voir rubrique 4.8).', 'Ulcérations gastro-intestinales', 'Des ulcérations à différents endroits du corps induites par le nicorandil peuvent survenir chez le même patient.', 'Elles sont réfractaires au traitement et, dans la plupart des cas, répondent uniquement à l’arrêt du traitement par nicorandil.', 'Si une ou plusieurs ulcération(s) apparaisse(nt), il convient d’arrêter définitivement le nicorandil (voir rubrique 4.8).', 'Les professionnels de santé doivent être avertis de l’importance du diagnostic rapide des ulcérations induites par le nicorandil et de l’arrêt rapide du traitement par nicorandil en cas d’ulcérations.', 'Sur la base des données disponibles, l’apparition des ulcérations peut intervenir peu après l’instauration du traitement par nicorandil mais également jusqu’à plusieurs années après le début du traitement par nicorandil.', 'Des hémorragies gastro-intestinales secondaires à une ulcération gastro-intestinale ont été rapportées avec le nicorandil.', 'La prudence est donc de rigueur lorsque l’utilisation concomitante d’acide acétylsalicylique ou d’AINS avec du nicorandil est envisagée (voir rubrique 4.5).', 'À un stade avancé, les ulcérations gastro-intestinales peuvent évoluer en perforation, formation de fistule ou d’abcès.', 'Les patients souffrant de maladie diverticulaire présentent un risque particulier de formation de fistule ou de perforation intestinale durant le traitement par nicorandil.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['L’utilisation concomitante d’un stimulateur de la guanylate cyclase soluble (tel que le riociguat) est contre-indiquée car elle peut entraîner une baisse importante de la pression artérielle.', 'Aux doses thérapeutiques, le nicorandil peut avoir un effet hypotenseur.', 'La dapoxétine doit être prescrite avec prudence chez les patients sous nicorandil en raison d’une diminution possible de la tolérance orthostatique.', 'Des perforations gastro-intestinales ont été rapportées lors de l’utilisation concomitante de nicorandil avec des corticoïdes.', 'La prudence est de rigueur lorsqu’une utilisation concomitante est envisagée.', 'La prudence est recommandée lorsque le nicorandil est associé avec d’autres médicaments susceptibles d’augmenter le taux de potassium (voir rubriques 4.4 et 4.8).', 'Le métabolisme du nicorandil n’est pas significativement affecté par la cimétidine (un inhibiteur du CYP) ou la rifampicine (un inducteur du CYP3A4).', 'Le nicorandil n’affecte pas la pharmacodynamique de l’acénocoumarol.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les fréquences sont définies comme suit : Très fréquent (≥ 1/10), Fréquent (≥ 1/100,', 'fréquent', 'Fréquent', 'Peu fréquent']);

  -- nifedipine (CIS 61545442, scored)
  m := pg_temp.jp_matrice_by_norm('nifedipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Inhibiteurs calciques sélectifs à effets vasculaires, code ATC : C08CA05.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['MAPAKNA LP est indiqué pour retarder l’accouchement en cas de menace d''accouchement prématuré chez les femmes enceintes adultes :', 'présentant des contractions utérines douloureuses régulières d’une durée d’au moins 30 secondes et survenant au moins 4 fois en 30 minutes ;', 'ayant un raccourcissement significatif du col clinique ou échographique ;', 'entre 22 et 37 semaines d’aménorrhée ;', 'présentant un rythme cardiaque fœtal normal.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit pas être utilisé dans les cas suivants :', 'Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'Age gestationnel inférieur à 22 semaines ou supérieur à 36 semaines complètes d’aménorrhée ;', 'Situations où la poursuite de la grossesse représente un risque pour la mère ou le fœtus :', 'o Chorioamniotite ;', 'o Hématome rétroplacentaire ;', 'o Hémorragie aigüe nécessitant l’accouchement immédiat ;', 'o Eclampsie et pré-éclampsie sévère nécessitant l’accouchement ;', 'o Rythme cardiaque fœtal anormal ;', 'o Infections utérines,', 'o Saignements consécutifs d’un placenta praevia.', 'Administration par voie systémique de bêtamimétiques dans les 48 heures précédentes ;']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'L''expérience clinique acquise avec la nifédipine est limitée chez les patientes ayant un âge gestationnel compris entre 22 et 27 semaines révolues d’aménorrhée, du fait du petit nombre de patientes traitées.', 'Les mesures de surveillance suivantes doivent être conduites chez la mère et le fœtus pendant la durée du traitement.', 'Durant la dose de charge : la pression artérielle de la patiente doit être surveillée régulièrement (toutes les 15 minutes) pendant 2 heures.', 'Les contractions utérines et le rythme cardiaque fœtal doivent être surveillés en continu.', 'Si le traitement est arrêté après la dose de charge, la pression artérielle de la patiente doit être surveillée durant les 8 heures qui suivent.', 'Tout au long du traitement, les signes et symptômes de surdosage doivent être surveillés.', 'La poursuite d’un traitement tocolytique au-delà de 48 heures n’a pas de bénéfice démontré.', 'Ainsi l’utilisation de la nifédipine doit être limitée à 48h maximum.', 'En cas de retard de croissance intra-utérin, la décision de poursuivre ou de réinitier l''administration de la nifédipine dépend de l''évaluation de la maturité fœtale.', 'En tant qu’inhibiteur de la contraction utérine, la nifédipine peut théoriquement favoriser le relâchement du muscle utérin et une hémorragie post-partum.', 'En conséquence, il convient de contrôler les pertes sanguines après l''accouchement.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['La nifédipine est métabolisée par le cytochrome P450 3A4, présent dans la muqueuse intestinale et dans le foie.', 'Les médicaments qui inhibent ou induisent ce système enzymatique sont donc susceptibles de modifier l’effet de premier passage hépatique ou la clairance de la nifédipine (voir rubrique 4.4).', 'Il faut tenir compte de l’importance et de la durée des interactions potentielles lors de la prise concomitante de nifédipine avec les médicaments listés ci-dessous.', 'Associations contre-indiquées', '+ Diltiazem', 'Augmentation importante des concentrations de nifédipine par diminution de son métabolisme hépatique par le diltiazem, avec risque d’hypotension sévère.', 'Associations déconseillées', '+ Ciclosporine', 'Risque d''addition d''effets indésirables à type de gingivopathies.', 'Utiliser une autre dihydropyridine.', '+ Dantrolène administré par perfusion', 'Chez l''animal des cas de fibrillations ventriculaires mortelles sont constamment observés lors de l''administration de vérapamil et de dantrolène IV.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquent', 'Peu fréquent', 'Angioœdème', 'Réaction anaphylactique/ anaphylactoïde,']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Les mesures de surveillance suivantes doivent être conduites chez la mère et le fœtus pendant la durée du traitement.', 'Durant la dose de charge : la pression artérielle de la patiente doit être surveillée régulièrement (toutes les 15 minutes) pendant 2 heures.', 'Les contractions utérines et le rythme cardiaque fœtal doivent être surveillés en continu.', 'Si le traitement est arrêté après la dose de charge, la pression artérielle de la patiente doit être surveillée durant les 8 heures qui suivent.', 'Tout au long du traitement, les signes et symptômes de surdosage doivent être surveillés.']);

  -- nicardipine (CIS 65984700, scored)
  m := pg_temp.jp_matrice_by_norm('nicardipine');
