  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active (la nicardipine) ou à l’un des excipients mentionnés à la rubrique 6.1,', 'Infarctus du myocarde datant de moins de 1 mois, angor instable (voir rubrique 4.4),', 'Sténose aortique sévère.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Ce médicament contient du lactose.', 'Les patients présentant une intolérance au galactose, un déficit total en lactase ou un syndrome de malabsorption du glucose et du galactose (maladies héréditaires rares) ne doivent pas prendre ce médicament.', 'Il est donc recommandé de prendre les précautions nécessaires pour éviter une chute excessive de la pression artérielle.', 'Insuffisance hépatique', 'La nicardipine doit être utilisée avec prudence chez les patients présentant une insuffisance hépatique.', 'Insuffisance rénale', 'La nicardipine doit être utilisée avec prudence chez les patients présentant une insuffisance rénale (voir rubrique 5.2).', 'Association avec des bêta-bloquants', 'Des précautions sont nécessaires lors de l’administration de la nicardipine en association avec un bêta-bloquant chez les patients présentant une diminution de la fonction cardiaque.', 'Maladie cardiaque ischémique', 'Il est donc recommandé de prendre les précautions nécessaires pour éviter une baisse excessive de la pression artérielle.', 'Insuffisance cardiaque']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées', '+ Dantrolène', 'Avec le dantrolène administré en perfusion :', 'Chez l’animal, des cas de fibrillations ventriculaires mortelles sont constamment observés lors de l’administration de vérapamil et de dantrolène IV.', 'L’association d’un antagoniste du calcium et de dantrolène est donc potentiellement dangereuse.', 'Cependant, quelques patients ont reçu l’association nifédipine et dantrolène sans inconvénient.', 'Associations faisant l''objet de précautions d’emploi', '+ Anticonvulsivants inducteurs enzymatiques (carbamazépine, fosphénytoïne, phénobarbital, phénytoïne, primidone)', 'Diminution des concentrations plasmatiques de la nicardipine par augmentation de son métabolisme hépatique.', 'Surveillance clinique et adaptation éventuelle de la posologie de la nicardipine pendant le traitement par l’anticonvulsivant et après son arrêt.', '+ Idélalisib', 'Majoration des effets indésirables de la nicardipine, à type d’hypotension orthostatique, notamment chez le sujet âgé.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquence indéterminée : Réaction anaphylactique', 'Fréquent : Sensations vertigineuses, Céphalées', 'Fréquent : Palpitations']);

  -- nitrendipine (CIS 67688899, scored)
  m := pg_temp.jp_matrice_by_norm('nitrendipine');
