  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l''hypertension artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament est contre-indiqué :', 'en cas d’hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'en cas d’angor instable ou dans les 4 semaines suivant un infarctus du myocarde aigu,', 'pendant la grossesse et l’allaitement (voir rubrique 4.6),', 'en association avec la rifampicine.', 'Par conséquent, l’administration concomitante de rifampicine est contre-indiquée (voir rubrique 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mise en garde', 'Insuffisance cardiaque décompensée', 'Les patients souffrant d’une insuffisance cardiaque décompensée doivent être traités avec précaution.', 'Troubles hépatiques', 'Chez les patients présentant des troubles hépatiques sévères, les effets de la nitrendipine peuvent être renforcés et prolongés.', 'Dans ce cas, les patients doivent être étroitement surveillés par un contrôle fréquent de leur pression artérielle au cours du traitement (voir rubriques 4.2 et 5.2).', 'Comme avec d’autres substances vasoactives, un angor peut survenir de façon très rare avec la nitrendipine, en particulier au début du traitement (données issues de la notification spontanée).', 'Les données issues des études cliniques confirment que la survenue de cet angor est peu fréquente (voir rubrique 4.8).', 'Ce médicament ne doit généralement pas être utilisé :', 'en cas d’association au dantrolène (perfusion) (voir rubrique 4.5).', 'Cytochrome CYP 3A4', 'La nitrendipine est métabolisée par le cytochrome CYP3A4.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['La nitrendipine est métabolisée par le cytochrome CYP3A4, situé dans la muqueuse intestinale et le foie.', 'Les médicaments connus pour inhiber ou stimuler ce système enzymatique peuvent donc modifier le métabolisme de premier passage ou la clairance de la nitrendipine.', 'L’importance et la durée de l''interaction doivent être prises en compte lors de l''administration concomitante de la nitrendipine avec de tels médicaments.', 'Associations contre-indiquées', '+ Rifampicine', 'L’efficacité de la nitrendipine pourrait donc être diminuée en cas d’administration concomitante avec la rifampicine.', 'L’utilisation de la nitrendipine en association à la rifampicine est en conséquence contre-indiquée (voir rubrique 4.3).', 'En cas d’administration concomitante avec les inhibiteurs du cytochrome CYP3A4, il convient de surveiller la tension artérielle et d’envisager éventuellement une diminution de la dose de nitrendipine.', 'Associations déconseillées', '+ Dantrolène (administré par perfusion)', 'Chez l''animal, des cas de fibrillations ventriculaires mortelles sont constamment observés lors de l''administration de vérapamil et de dantrolène par voie IV.', 'L''association d''un antagoniste du calcium et de dantrolène est donc potentiellement dangereuse.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥ 1/10),', 'Fréquent (≥ 1/100 à', 'Peu fréquent (≥ 1/1 000 à']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Dans ce cas, les patients doivent être étroitement surveillés par un contrôle fréquent de leur pression artérielle au cours du traitement (voir rubriques 4.2 et 5.2).']);

  -- isradipine (CIS 67966754, scored)
  m := pg_temp.jp_matrice_by_norm('isradipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : INHIBITEURS DES CANAUX CALCIQUES SÉLECTIFS VASCULAIRES, code ATC : C08CA03.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l’hypertension artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité connue à l’isradipine, aux autres inhibiteurs des canaux calciques de la famille des dihydropyridines ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Comme avec les autres inhibiteurs des canaux calciques, ICAZ LP 2,5 mg, gélule ne doit pas être utilisé chez les patients présentant les conditions suivantes :', 'Choc cardiogénique,', 'Angor instable,', 'Infarctus du myocarde datant de moins d’un mois.', 'Enfant : l''absence de données cliniques contre-indique l''utilisation de ce produit chez l''enfant.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Il est recommandé d’adapter la posologie chez les personnes âgées, et les insuffisants hépatiques (voir rubrique 4.2).', 'Il est recommandé d’adapter la posologie avec prudence chez les insuffisants rénaux et les insuffisants cardiaques chroniques.', 'Des précautions doivent être prises chez les patients ayant une maladie du nœud sinusal confirmée ou fortement suspectée et qui ne sont pas appareillés avec un pacemaker.', 'Prendre des précautions particulières en cas de faible pression systolique ou de sténose aortique sévère.', 'Une crise angineuse peut survenir principalement chez des patients présentant une cardiopathie ischémique.', 'Lors de l’initiation du traitement ou lors de l’augmentation trop rapide de la posologie chez ces patients, la fréquence, la durée et la sévérité des crises angineuses peuvent se majorer.', 'ICAZ LP 2,5 mg, gélule doit être arrêté en cas de réaction d’hypersensibilité à ce médicament.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées', 'Dantrolène', 'Avec le dantrolène administré par perfusion : chez l''animal, des cas de fibrillations ventriculaires mortelles sont constamment observés lors de l''administration de vérapamil et de dantrolène IV.', 'L''association d''un antagoniste du calcium et de dantrolène est donc potentiellement dangereuse.', 'Cependant, quelques patients ont reçu l''association nifédipine et dantrolène sans inconvénient.', 'Associations faisant l''objet de précautions d’emploi', 'Itraconazole, kétoconazole', 'Risque majoré d''effets indésirables, notamment d’œdèmes, par diminution du métabolisme hépatique de la dihydropyridine.', 'Surveillance clinique et adaptation éventuelle de la posologie de la dihydropyridine pendant le traitement par l’itraconazole ou le kétoconazole et après leur arrêt.', 'Anticonvulsivants inducteurs enzymatiques (carbamazepine, fosphenytoine, phénobarbital, phenytoine, primidone, etc.)', 'Diminution des concentrations plasmatiques de l''antagoniste du calcium par augmentation de son métabolisme hépatique par l’inducteur.', 'Surveillance clinique et adaptation éventuelle de la posologie de l''antagoniste du calcium pendant le traitement par l''inducteur et après son arrêt.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquentes : céphalées', 'Fréquentes : sensations vertigineuses', 'Fréquentes : tachycardie, palpitations']);

  -- amlodipine (CIS 69622809, scored)
  m := pg_temp.jp_matrice_by_norm('amlodipine');
