  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension', 'Traitement de l''hypertension artérielle essentielle.', 'Insuffisance cardiaque chronique', 'Traitement de l''insuffisance cardiaque chronique stable, légère et modérée, en association aux traitements conventionnels chez des patients âgés de 70 ans ou plus.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l''un des excipients mentionnés à la rubrique 6.1.', 'Insuffisance hépatique ou altération de la fonction hépatique.', 'Insuffisance cardiaque aiguë, choc cardiogénique ou épisodes de décompensation de l''insuffisance cardiaque nécessitant un traitement inotrope intraveineux.', 'De plus, comme pour d''autres bêta-bloquants, NEBIVOLOL ALMUS est contre-indiqué dans les cas suivants :', 'maladie du sinus incluant bloc sino-auriculaire,', 'blocs auriculo-ventriculaires des second et troisième degrés (non appareillés),', 'antécédents de bronchospasme et d''asthme bronchique,', 'phéochromocytome non traité,', 'acidose métabolique,', 'bradycardie (fréquence cardiaque', 'hypotension (pression artérielle systolique', 'troubles circulatoires périphériques dans leurs formes sévères.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Les mises en garde et précautions suivantes sont communes aux bêta-bloquants:', 'Anesthésie générale', 'La poursuite du traitement par bêta-bloquant diminue le risque d''arythmie pendant l''induction et l''intubation.', 'Si le traitement par bêta-bloquant est arrêté en vue d''une intervention, il sera suspendu pour au moins 24 heures avant.', 'Il convient d''observer une prudence particulière avec certains anesthésiques dépresseurs myocardiques.', 'Le patient peut être protégé d''une prédominance vagale par l''administration d''atropine par voie intraveineuse.', 'Cardiovasculaires', 'Généralement, les bêta-bloquants ne doivent pas être utilisés chez les patients présentant une insuffisance cardiaque congestive non traitée, à moins qu''elle ne soit stabilisée.', 'Chez les patients présentant une cardiopathie ischémique, le traitement par bêta-bloquant devra être diminué progressivement c''est-à-dire sur 1 à 2 semaines.', 'Si nécessaire, un traitement substitutif devra être commencé en même temps pour éviter une aggravation de l''angor.', 'Les bêta-bloquants doivent être administrés avec prudence:', 'chez les patients souffrant de troubles circulatoires périphériques (maladie ou syndrome de Raynaud, claudication intermittente), une aggravation de ces troubles pouvant apparaître,']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Interactions pharmacodynamiques', 'Les interactions suivantes sont communes aux bêta-bloquants:', 'Associations déconseillées', '+ Anti-arythmiques de classe I (quinidine, hydroquinidine, cibenzoline, flecaïnide, disopyramide, lidocaïne, mexilétine, propafénone)', 'Potentialisation de l''effet sur le temps de conduction auriculo-ventriculaire et augmentation de l''effet inotrope négatif (voir rubrique 4.4).', '+ Antagonistes calciques du type vérapamil ou diltiazem', 'Effet négatif sur la contractilité et la conduction auriculo-ventriculaire.', 'L''administration de vérapamil par voie IV chez les patients traités par bêta-bloquants peut induire une hypotension sévère et un bloc auriculo-ventriculaire (voir rubrique 4.4).', '+ Anti-hypertenseurs d''action centrale (clonidine, guanfacine, moxonidine, méthyldopa, rilménidine)', 'Il existe un risque accru d''« hypertension rebond » en cas d''arrêt brutal du traitement par anti-hypertenseur central, en particulier s''il a lieu avant l''arrêt du bêta-bloquant.', 'Associations faisant l''objet de précautions d’emploi', '+ Anti-arythmiques de classe III (amiodarone)']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquent (1/100 à 1/10)', 'Peu fréquent (1/1000 à 1/100)', 'Très rare (≤ 1/10000)']);

  -- atorvastatine (CIS 61411404, scored)
  m := pg_temp.jp_matrice_by_norm('atorvastatine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Hypolipidémiants, inhibiteurs de l''HMG-CoA réductase, Code ATC: C10AA05.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypercholestérolémie', 'Prévention des maladies cardiovasculaires']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['ATORVASTATINE ACCORD est contre-indiqué chez les patients:', 'présentant une hypersensibilité à la substance active ou à l''un des excipients mentionnés à la rubrique 6.1.', 'atteints d''une affection hépatique évolutive ou ayant des élévations persistantes et inexpliquées des transaminases sériques supérieure à trois fois la limite supérieure de la normale.', 'chez les femmes enceintes, allaitantes ou en âge de procréer et n''utilisant pas de méthodes contraceptives fiables (voir rubrique 4.6).', 'traités avec les agents antiviraux contre l’hépatite C glécaprévir/pibrentasvir.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Dans quelques cas, il a été rapporté que les statines induisaient de novo ou aggravaient une myasthénie préexistante ou une myasthénie oculaire (voir rubrique 4.8).', 'ATORVASTATINE ACCORD doit être arrêté en cas d’aggravation des symptômes.', 'Des récurrences ont été rapportées lorsque la même statine ou une statine différente a été (ré)administrée.', 'Effets hépatiques', 'Des épreuves fonctionnelles hépatiques doivent être réalisées avant le début du traitement, lors de l''adaptation posologique puis régulièrement après l''instauration de celui-ci.', 'Des tests fonctionnels hépatiques doivent être réalisés chez les patients développant des signes ou symptômes évoquant une altération hépatique.', 'En cas d''élévation du taux sérique des transaminases, une surveillance s''impose jusqu''à normalisation.', 'En cas d''augmentation persistante des transaminases dépassant 3 fois la limite supérieure de la normale (LSN), la posologie devra être diminuée ou ATORVASTATINE ACCORD devra être arrêté (voir rubrique 4.8).', 'ATORVASTATINE ACCORD doit être utilisé avec prudence chez les patients consommant des quantités importantes d''alcool et/ou ayant des antécédents d''affection hépatique.', 'Prévention des AVC par diminution agressive des taux de cholestérol (Etude SPARCL)', 'Ce risque élevé est particulièrement observé chez des patients ayant déjà fait un AVC hémorragique ou un infarctus lacunaire à l''inclusion de l''étude.', 'Chez les patients ayant un antécédent d''AVC hémorragique ou d''infarctus lacunaire, la balance bénéfice/risque de l''atorvastatine 80 mg est incertaine.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Effet des médicaments co-administrés sur l’atorvastatine', 'L’atorvastatine est métabolisée par le cytochrome P450 3A4 (CYP3A4) et est un substrat des transporteurs hépatiques, polypeptides transporteurs d’anions organiques 1B1 (OATP1B1) et 1B3 (OATP1B3).', 'Les métabolites de l’atorvastatine sont des substrats de l’OATP1B1.', 'L''administration concomitante de médicaments inhibiteurs du CYP3A4 ou des transporteurs protéiques peut augmenter les concentrations plasmatiques d''atorvastatine et à un risque majoré de myopathie.', 'Le risque peut aussi être augmenté lors de l''administration concomitante d''atorvastatine avec d''autres médicaments pouvant induire des myopathies, tels que les fibrates et l''ézétimibe (voir rubrique 4.4).', 'Inhibiteurs du cytochrome CYP3A4', 'Les concentrations plasmatiques d''atorvastatine sont augmentées de façon importante lors de l''association avec les inhibiteurs puissants du CYP3A4 (voir Tableau 1 et les informations spécifiques ci-dessous).', 'Les inhibiteurs modérés du CYP3A4 (tels que érythromycine, diltiazem, vérapamil et le fluconazole) peuvent augmenter les concentrations plasmatiques d''atorvastatine (voir Tableau 1).', 'Une majoration du risque de myopathie a été observée lors de l''administration concomitante d''érythromycine et de statines.', 'Aucune étude d''interaction évaluant les effets de l''amiodarone ou du vérapamil sur l''atorvastatine n''a été réalisée.', 'L''amiodarone et le vérapamil étant tous deux connus pour inhiber l''activité du CYP3A4, leur association avec l''atorvastatine peut entraîner une augmentation de l''exposition à l''atorvastatine.', 'C''est pourquoi, une dose initiale plus faible d''atorvastatine doit être prescrite et une surveillance clinique adéquate du patient doit être mise en place.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les fréquences estimées des effets indésirables sont classées selon la convention suivante: fréquent (≥ 1/100, fréquence indéterminée (ne peut être estimée sur la base des données disponibles).', 'Fréquent: rhinopharingite.', 'Rare: thrombocytopénie.', 'Fréquent: réactions allergiques.', 'Très rare: anaphylaxie.', 'Fréquent: hyperglycémie.', 'Peu fréquent: hypoglycémie, prise de poids, anorexie.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['En cas d''élévation du taux sérique des transaminases, une surveillance s''impose jusqu''à normalisation.']);

  -- enalapril (CIS 69468186, scored)
  m := pg_temp.jp_matrice_by_norm('enalapril');
