  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l’hypertension artérielle.', 'Traitement de l’insuffisance cardiaque symptomatique.', 'Prévention de l’insuffisance cardiaque symptomatique chez des patients ayant une dysfonction ventriculaire gauche asymptomatique (fraction d’éjection ≤ 35 %)', '(Voir rubrique 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active, ou à l’un des excipients mentionnés à la rubrique 6.1 ou tout autre IEC.', 'Antécédent d''angio-œdème lié à un traitement antérieur par un IEC.', 'Angio-œdème héréditaire ou idiopathique.', 'Deuxième et troisième trimestres de la grossesse (voir rubriques 4.4 et 4.6).', 'L’association de ENALAPRIL ACCORD à des médicaments contenant de l''aliskiren est contre-indiquée chez les patients présentant un diabète ou une insuffisance rénale (DFG 2) (voir rubriques 4.5 et 5.1).', 'L’utilisation concomitante avec l’association sacubitril/valsartan.', 'ENALAPRIL ACCORD ne doit pas débuter moins de 36 heures après la dernière dose de l’association sacubitril/valsartan (voir rubriques 4.4 et 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hypotension symptomatique', 'Une hypotension symptomatique est rarement observée chez les patients hypertendus non compliqués.', 'Chez les patients ayant une insuffisance cardiaque, associée ou non à une insuffisance rénale, une hypotension symptomatique a été observée.', 'Chez ces patients, le traitement doit être débuté sous surveillance médicale et les patients doivent être suivis étroitement chaque fois que la dose de ENALAPRIL ACCORD et/ou de diurétique est ajustée.', 'Si une hypotension survient, le patient doit être mis en position couchée et, si nécessaire, doit recevoir une perfusion intraveineuse de solution salée isotonique.', 'Chez certains patients insuffisants cardiaques qui ont une pression artérielle normale ou basse, une baisse supplémentaire de la pression artérielle systémique peut survenir avec ENALAPRIL ACCORD.', 'Cet effet est attendu et n''est habituellement pas une raison pour arrêter le traitement.', 'Si l''hypotension devient symptomatique, une réduction de la dose et/ou l''arrêt du diurétique et/ou de ENALAPRIL ACCORD peuvent être nécessaires.', 'Sténose aortique ou mitrale/cardiomyopathie hypertrophique', 'Altération de la fonction rénale', 'Si elle est diagnostiquée rapidement et traitée de façon appropriée, l’insuffisance rénale lorsqu’elle est associée à un traitement avec l’énalapril est habituellement réversible.', 'Une réduction de la dose et/ou l''arrêt du diurétique peuvent être nécessaires.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments augmentant le risque d’angio-œdème', 'L’utilisation concomitante d’IEC avec l’association sacubitril/valsartan est contre-indiquée en raison du risque accru d’angio-œdème (voir rubrique 4.3 et 4.4).', 'L’utilisation concomitante des IEC avec le racécadotril, les inhibiteurs mTOR (tels que sirolimus, everolimus, temsirolimus) et la vildagliptine peut entrainer un risque accru d’angio-œdème (voir rubrique 4.4).', 'Double blocage du système rénine-angiotensine-aldostérone (SRAA)', 'Diurétiques épargneurs de potassium, suppléments potassiques ou d''autres médicaments susceptibles d''augmenter le taux de potassium sérique', 'Bien que la kaliémie demeure habituellement dans les limites de la normale, une hyperkaliémie peut survenir chez certains patients traités par ENALAPRIL ACCORD.', 'Par conséquent, l’association d’ENALAPRIL ACCORD avec les médicaments susmentionnés n’est pas recommandée.', 'Si une utilisation concomitante est indiquée, elle doit se faire avec précaution et être accompagnée d’une surveillance fréquente de la kaliémie.', 'Ciclosporine', 'Une hyperkaliémie peut survenir lors de l’utilisation concomitante d’IEC avec de la ciclosporine.', 'Une surveillance de la kaliémie est recommandée.', 'Héparine']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent', '(≥ 1/10)', 'Fréquent', '(≥ 1/100 et', 'Peu fréquent', '(≥ 1/10 000 et']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Chez ces patients, le traitement doit être débuté sous surveillance médicale et les patients doivent être suivis étroitement chaque fois que la dose de ENALAPRIL ACCORD et/ou de diurétique est ajustée.', 'Altération de la fonction rénale']);

  -- ramipril (CIS 63624696, scored)
  m := pg_temp.jp_matrice_by_norm('ramipril');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs de l’enzyme de conversion (IEC) non associés, code ATC : C09AA05.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l''hypertension.', 'Prévention cardiovasculaire : réduction de la morbidité et la mortalité cardiovasculaires chez les patients présentant :', 'o une maladie cardiovasculaire athérothrombotique manifeste (antécédents de maladie coronaire ou d''accident vasculaire cérébral, ou artériopathie périphérique) ou', 'o un diabète avec au moins un facteur de risque cardiovasculaire (voir rubrique 5.1).', 'Traitement de la néphropathie :', 'o néphropathie glomérulaire diabétique débutante, telle que définie par la présence d''une microalbuminurie ;', 'o néphropathie glomérulaire diabétique manifeste, telle que définie par une macroprotéinurie chez les patients présentant au moins un facteur de risque cardiovasculaire (voir rubrique 5.1) ;', 'o néphropathie glomérulaire non-diabétique manifeste, telle que définie par une macroprotéinurie ≥ 3 g/jour (voir rubrique 5.1).', 'Traitement de l''insuffisance cardiaque symptomatique.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité au ramipril, à tout autre IEC (inhibiteur de l''enzyme de conversion) ou à l''un des excipients mentionnés à la rubrique 6.1 ;', 'Antécédent d''angio-œdème (héréditaire, idiopathique ou du fait d''un antécédent d''angio‑œdème avec les IEC ou les ARA-II) ;', 'Utilisation concomitante avec l’association sacubitril/valsartan (voir rubriques 4.4 et 4.5) ;', 'Traitements extracorporels impliquant une mise en contact du sang avec des surfaces chargées négativement (voir rubrique 4.5) ;', 'Sténose artérielle rénale bilatérale significative, ou sténose artérielle rénale sur rein fonctionnellement unique ;', '2ème et 3ème trimestres de la grossesse (voir rubriques 4.4 et 4.6) ;', 'Le ramipril ne doit pas être utilisé chez les patients hypotendus ou instables hémodynamiquement.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Populations particulières', 'Grossesse', 'Les IEC comme le ramipril et les antagonistes des récepteurs de l’angiotensine II (ARA II) ne doivent pas être débutés au cours de la grossesse.', 'En cas de diagnostic de grossesse, le traitement par IEC/ARA II doit être arrêté immédiatement et si nécessaire un traitement alternatif sera débuté (voir rubriques 4.3 et 4.6).', 'Patients à risque particulier d’hypotension', 'Patients à système rénine-angiotensine-aldostérone fortement activé', 'Une activation significative du système rénine-angiotensine-aldostérone est à prévoir, et une surveillance médicale, y compris le contrôle de la pression artérielle, est nécessaire par exemple en cas de :', 'o patients ayant une hypertension sévère ;', 'o patients ayant une insuffisance cardiaque congestive décompensée ;', 'o patients ayant une obstruction hémodynamique significative au remplissage ou à l’éjection du ventricule gauche (par exemple une sténose de la valve aortique ou mitrale) ;', 'o patients ayant une sténose artérielle rénale unilatérale avec un second rein fonctionnel ;', 'o patients ayant ou susceptibles de développer une déplétion hydrosodée (y compris les patients sous diurétiques) ;']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', 'L’utilisation concomitante des IEC avec l’association sacubitril/valsartan est contre-indiquée car elle augmente le risque d’angio-œdème (voir rubriques 4.3 et 4.4).', 'Le traitement avec ramipril ne doit pas être débuté moins de 36 heures après la prise de la dernière dose de l’association sacubitril/valsartan.', 'L’association sacubitril/valsartan ne doit pas être débutée moins de 36 heures après la dernière dose de ramipril.', 'Si un tel traitement est requis, le recours à un type différent de membrane de dialyse ou à une classe différente d''agents antihypertenseurs doit être envisagé.', 'Associations faisant l''objet de précautions d’emploi', 'Une hyperkaliémie peut survenir, par conséquent, une surveillance étroite du potassium sérique est requise.', 'Une potentialisation du risque d’hypotension est à prévoir (voir rubrique 4.2 concernant les diurétiques).', '+ Sympathomimétiques vasopresseurs et autres substances (telles l’isoprotérénol, la dobutamine, la dopamine, l’épinéphrine) susceptibles de réduire l’effet antihypertenseur de RAMIPRIL ALMUS', 'Une surveillance de la pression artérielle est recommandée.', '+ Allopurinol, immunosuppresseurs, corticoïdes, procaïnamide, cytostatiques et autres substances susceptibles de modifier la numération sanguine', 'Probabilité accrue de réactions hématologiques (voir rubrique 4.4).']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les réactions indésirables graves comportent un angio-œdème, une hyperkaliémie, une altération de la fonction rénale ou hépatique, une pancréatite, des réactions cutanées sévères et une neutropénie/ag', 'Très fréquentes (≥ 1/10) ; fréquentes (≥ 1/100 à Au sein de chaque groupe de fréquence, les effets indésirables sont présentés par ordre décroissant de gravité.', 'Fréquents', 'Peu fréquents']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Une activation significative du système rénine-angiotensine-aldostérone est à prévoir, et une surveillance médicale, y compris le contrôle de la pression artérielle, est nécessaire par exemple en cas de :']);

  -- captopril (CIS 64429514, scored)
  m := pg_temp.jp_matrice_by_norm('captopril');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs de l''enzyme de conversion de l’angiotensine, code ATC : C09AA01');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['NOYADA est indiqué dans le traitement de :', '- l’hypertension artérielle', '- l’infarctus du myocarde :', 'o Traitement de courte durée (4 semaines) : NOYADA est indiqué dans les 24 premières heures chez les patients en situation hémodynamique stable.', 'o Prévention à long terme de l’insuffisance cardiaque symptomatique : NOYADA est indiqué chez les patients cliniquement stables avec dysfonction ventriculaire gauche asymptomatique (fraction d''éjection ≤ à 40 %).', '- la néphropathie diabétique du diabète de type I : NOYADA est indiqué dans le traitement de la néphropathie diabétique macroprotéinurique du diabète insulinodépendant (voir rubrique 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité au captopril, à tout autre inhibiteur de l''enzyme de conversion de l''angiotensine ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Antécédent d’angiœdème lié à la prise d''un inhibiteur de l''enzyme de conversion de l''angiotensine.', 'Angiœdème héréditaire/idiopathique.', '2ème et 3ème trimestres de la grossesse (voir rubriques 4.4 et 4.6).', 'Utilisation concomitante avec un traitement par sacubitril/valsartan.', 'Le traitement par cilazapril ne doit pas être débuté moins de 36 heures après la dernière dose de sacubitril/valsartan (voir également rubriques 4.4 et 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hypotension', 'De rares cas d''hypotension ont été observés chez des patients présentant une hypertension non compliquée.', 'La déplétion hydrosodée doit être corrigée avant d''administrer un inhibiteur de l''enzyme de conversion et une dose initiale plus faible doit être envisagée.', 'La prudence est de rigueur en cas d’augmentation de la dose de captopril ou du diurétique chez les patients présentant une insuffisance cardiaque.', 'Si une hypotension se développe, le patient doit être placé en position allongée.', 'Un remplissage volémique par une solution saline administrée par voie intraveineuse peut être nécessaire.', 'Hypertension rénovasculaire', 'La perte de la fonction rénale peut survenir même en cas de modification légère de la créatinine sérique.', 'Chez ces patients, le traitement doit être initié sous surveillance médicale étroite avec des posologies faibles, une titration prudente et un suivi de la fonction rénale.', 'Insuffisance rénale', 'Une surveillance régulière du potassium et de la créatinine relève de la pratique médicale habituelle chez ces patients.', 'Hypersensibilité/angiœdème']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Diurétiques épargneurs de potassium, suppléments potassiques ou substituts de sel contenant du potassium :', 'Bien que la kaliémie demeure habituellement dans les limites de la normale, une hyperkaliémie peut survenir chez certains patients traités par captopril.', 'Par conséquent, l’association du captopril avec les médicaments susmentionnés n’est pas recommandée.', 'Si une utilisation concomitante est indiquée, elle doit se faire avec précaution et être accompagnée d’une surveillance fréquente de la kaliémie.', 'Ciclosporine :', 'Une hyperkaliémie peut survenir lors de l’utilisation concomitante d’IEC avec de la ciclosporine.', 'Une surveillance de la kaliémie est recommandée.', 'Héparine :', 'Une hyperkaliémie peut survenir lors de l’utilisation concomitante d’IEC avec de l’héparine.', 'Diurétiques (thiazidiques ou diurétique de l’anse) :', 'Un traitement préalable avec des diurétiques à dose élevée peut provoquer une hypovolémie et un risque d''hypotension lors de l''instauration du traitement par le captopril (voir rubrique 4.4).', 'Les effets hypotenseurs peuvent être réduits par arrêt du diurétique, par augmentation de la prise sodée ou hydrique et l''initiation d''un traitement par une faible dose de captopril.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables rapportés avec le captopril et présentés ci-dessous sont classés par ordre de fréquence, selon la convention suivante : effets très fréquents (≥ 1/10), fréquents (≥ 1/100 ;', 'Fréquent', 'Peu fréquent']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['La perte de la fonction rénale peut survenir même en cas de modification légère de la créatinine sérique.', 'Chez ces patients, le traitement doit être initié sous surveillance médicale étroite avec des posologies faibles, une titration prudente et un suivi de la fonction rénale.', 'Une surveillance régulière du potassium et de la créatinine relève de la pratique médicale habituelle chez ces patients.']);

  -- lisinopril (CIS 66729161, scored)
  m := pg_temp.jp_matrice_by_norm('lisinopril');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Inhibiteurs de l’enzyme de conversion - Code ATC : C09AA03');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle', 'Traitement de l''hypertension artérielle.', 'Insuffisance cardiaque', 'Traitement de l''insuffisance cardiaque symptomatique.', 'Infarctus du myocarde en phase aiguë', 'Traitement à court terme (6 semaines), chez les patients en situation hémodynamique stable, de l''infarctus du myocarde en phase aiguë, dans les 24 premières heures.', 'Complications rénales du diabète', 'Traitement de l''atteinte rénale chez l’hypertendu diabétique de type II présentant une néphropathie débutante (voir rubrique 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l''un des excipients mentionnés à la rubrique 6.1 ou à tout autre inhibiteur de l''enzyme de conversion (IEC).', 'Antécédent d''angiœdème associé à la prise d''un inhibiteur de l''enzyme de conversion.', 'Utilisation concomitante de Zestril avec un traitement par sacubitril/valsartan.', 'Le traitement par Zestril ne doit pas être débuté moins de 36 heures après la dernière dose de sacubitril/valsartan (voir également rubriques 4.4 et 4.5).', 'Angiœdème héréditaire ou idiopathique.', '2ème et 3ème trimestres de la grossesse (voir rubriques 4.4 et 4.6).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hypotension symptomatique', 'Au cours du traitement de l''hypertension artérielle non compliquée, il est rare d’observer une hypotension symptomatique.', 'En cas d''insuffisance cardiaque, accompagnée ou non d''insuffisance rénale, des cas d''hypotension symptomatique ont été observés.', 'Ils sont plus fréquents en cas d''insuffisance cardiaque sévère (définie par l''utilisation de fortes doses de diurétiques de l''anse, la présence d''hyponatrémie ou d''insuffisance rénale fonctionnelle).', 'En cas de risque accru d''hypotension symptomatique, l''initiation du traitement et l''adaptation posologique doivent faire l''objet d''un suivi étroit.', 'En cas de survenue d''une hypotension, le patient doit être mis en position allongée et recevoir, si nécessaire, une perfusion IV de sérum salé.', 'Chez certains patients insuffisants cardiaques présentant une pression artérielle normale ou basse, Zestril peut provoquer une baisse supplémentaire de la pression artérielle.', 'Cet effet est prévisible et ne constitue généralement pas un motif d''arrêt du traitement.', 'Si l''hypotension devient symptomatique, une diminution de la posologie, ou un arrêt du traitement par Zestril peuvent être nécessaires.', 'Hypotension à la phase aiguë de l''infarctus du myocarde', 'Au cours des 3 premiers jours suivant l''infarctus, la posologie doit être diminuée si la pression artérielle systolique est inférieure ou égale à 120 mmHg.', 'La posologie d''entretien doit être réduite à 5 mg/j, ou même temporairement à 2,5 mg/jour si la pression artérielle systolique est inférieure ou égale à 100 mmHg.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Agents antihypertenseurs', 'Lorsque Zestril est associé avec d’autres agents antihypertenseurs (par exemple la nitroglycérine et autres nitrates, ou autres vasodilatateurs), une baisse supplémentaire de la pression artérielle peut survenir.', 'Médicaments augmentant le risque d’angio-œdème :', 'L’utilisation concomitante d’IEC avec l’association sacubitril/valsartan est contre-indiquée en raison du risque accru d’angio-oedème (voir rubriques 4.3 et 4.4).', 'Diurétiques', 'Lorsqu''un diurétique est associé à Zestril, les effets antihypertenseurs sont en général additifs.', 'Le risque d''hypotension symptomatique peut-être limité en arrêtant le diurétique avant de débuter le traitement par Zestril (voir rubriques 4.2 et 4.4).', 'Potassium, diurétiques épargneurs de potassium, substituts de sel contenant du potassium et autres médicaments pouvant augmenter le taux de potassium sérique', 'Bien que la kaliémie demeure habituellement dans les limites de la normale, une hyperkaliémie peut survenir chez certains patients traités par Zestril.', 'Par conséquent, l’association du Zestril avec les médicaments susmentionnés n’est pas recommandée.', 'Si une utilisation concomitante est indiquée, elle doit se faire avec précaution et être accompagnée d’une surveillance fréquente de la kaliémie.', 'Si Zestril est associé à un diurétique hypokaliémiant, l''hypokaliémie provoquée par le diurétique peut être améliorée.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très rare : dépression médullaire, anémie, thrombocytopénie, leucopénie, neutropénie, agranulocytose (voir rubrique 4.4), anémie hémolytique, lymphadénopathie, maladie autoimmune.', 'Fréquence indéterminée : réactions anaphylactiques/anaphylactoïdes', 'Fréquent : étourdissements, céphalées', 'Peu fréquent : troubles de l’humeur, paresthésie, vertiges, troubles du goût, troubles du sommeil, hallucinations.']);

