  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hyperkaliémie', 'En raison du mécanisme d''action, une hyperkaliémie peut survenir sous éplérénone.', 'La kaliémie doit être contrôlée chez tous les patients lors de l’initiation du traitement et lors des modifications de posologie.', 'L''administration de suppléments potassiques après le début du traitement par éplérénone n''est pas recommandée en raison du risque accru d''hyperkaliémie.', 'Une baisse de la kaliémie a été observée en cas de diminution de la posologie d’éplérénone.', 'Une étude a montré que l’association d''hydrochlorothiazide à un traitement par l’éplérénone a contrebalancé l’augmentation de la kaliémie.', 'Le risque d''hyperkaliémie peut augmenter lorsque l''éplérénone est utilisée en association avec un IEC et/ou un ARA II.', 'L''association d''un IEC et d’un ARA II avec l''éplérénone ne doit pas être utilisée (voir rubriques 4.3 et 4.5).', 'Insuffisance rénale', 'Chez les patients présentant une insuffisance rénale, notamment une microalbuminurie diabétique, la kaliémie doit être contrôlée régulièrement.', 'Le risque d''hyperkaliémie augmente avec la diminution de la fonction rénale.', 'Ils doivent donc être traités avec précaution.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Interactions pharmacodynamiques', '+ Diurétiques épargneurs de potassium et suppléments potassiques', 'En raison du risque accru d’hyperkaliémie, l’éplérénone ne doit pas être administrée à des patients recevant d’autres diurétiques épargneurs de potassium ou des suppléments potassiques (voir rubrique 4.3).', 'Les diurétiques épargneurs de potassium peuvent aussi majorer l’effet des médicaments antihypertenseurs et des autres diurétiques.', '+ IEC, ARA II', 'Le risque d''hyperkaliémie peut augmenter lorsque l''éplérénone est utilisée en association avec un IEC et/ou un ARAII.', 'Une surveillance étroite de la kaliémie et de la fonction rénale est recommandée, en particulier chez les patients à risque d’insuffisance rénale, par exemple, les patients âgés.', 'La triple association d''un IEC et d’un ARAII avec l''éplérénone ne doit pas être utilisée (voir rubriques 4.3 et 4.4).', '+ Lithium', 'Aucune étude d’interaction médicamenteuse n’a été conduite avec le lithium.', 'Cependant, chez des patients recevant du lithium, des diurétiques et des inhibiteurs de l’enzyme de conversion (IEC), une toxicité du lithium a été observée (voir rubrique 4.4).', 'L’administration concomitante d’éplérénone et de lithium doit être évitée.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥1/10)', 'Fréquent (≥1/100,', 'Peu fréquent (≥1/1 000,', 'Rare (≥1/10 000,']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Hyperkaliémie', 'En raison du mécanisme d''action, une hyperkaliémie peut survenir sous éplérénone.', 'La kaliémie doit être contrôlée chez tous les patients lors de l’initiation du traitement et lors des modifications de posologie.', 'L''administration de suppléments potassiques après le début du traitement par éplérénone n''est pas recommandée en raison du risque accru d''hyperkaliémie.', 'Une baisse de la kaliémie a été observée en cas de diminution de la posologie d’éplérénone.']);

  -- naftidrofuryl (CIS 61621776, scored)
  m := pg_temp.jp_matrice_by_norm('naftidrofuryl');
